# wraps body.glb into model.js (base64) so index.html can load the 3d model when opened via file://
# (browsers block fetch() of local files, but a <script src> works)
# usage: python tools/build_model.py path/to/body.glb
import base64, pathlib, sys

glb = pathlib.Path(sys.argv[1]).read_bytes()
out = pathlib.Path(__file__).resolve().parent.parent / 'model.js'
out.write_text(
    '// generated by tools/build_model.py - do not edit\n'
    '// 3d model: z-anatomy (cc by-sa 4.0), based on bodyparts3d (c) dbcls (cc by 4.0)\n'
    'window.BODY_GLB = "' + base64.b64encode(glb).decode('ascii') + '";\n',
    encoding='ascii')
print(f'wrote {out} ({out.stat().st_size / 1e6:.1f} MB)')
